package main

import (
	"database/sql"
	"errors"
	"path/filepath"

	_ "github.com/mattn/go-sqlite3"
)

type Ledger struct {
	db *sql.DB
}

func NewLedger(dataDir string) *Ledger {
	if err := openAndMigrate(dataDir); err != nil {
		panic(err)
	}

	db, err := sql.Open("sqlite3", "file:"+filepath.Join(dataDir, "ledger.db")+"?_journal_mode=WAL&_busy_timeout=5000")
	if err != nil {
		panic(err)
	}
	// A single SQLite connection serializes access and avoids SQLITE_BUSY
	// between the submission path and the processing loop.
	db.SetMaxOpenConns(1)
	db.SetMaxIdleConns(1)
	return &Ledger{db: db}
}

func openAndMigrate(dataDir string) error {
	db, err := sql.Open("sqlite3", "file:"+filepath.Join(dataDir, "ledger.db")+"?_journal_mode=WAL&_busy_timeout=5000")
	if err != nil {
		return err
	}
	defer db.Close()
	if err := db.Ping(); err != nil {
		return err
	}
	if _, err := db.Exec("PRAGMA synchronous = FULL"); err != nil {
		return err
	}
	if _, err := db.Exec(`CREATE TABLE IF NOT EXISTS transactions (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		key TEXT NOT NULL,
		account TEXT NOT NULL,
		amount INTEGER NOT NULL,
		status TEXT NOT NULL DEFAULT 'pending'
	)`); err != nil {
		return err
	}
	if _, err := db.Exec(`CREATE TABLE IF NOT EXISTS accounts (
		name TEXT PRIMARY KEY,
		balance INTEGER NOT NULL DEFAULT 0
	)`); err != nil {
		return err
	}

	// Older versions allowed multiple rows for a key. Retain one row per key
	// (preferring a completed row) so the key can be made authoritative.
	if _, err := db.Exec(`DELETE FROM transactions WHERE id IN (
		SELECT id FROM (
			SELECT id, ROW_NUMBER() OVER (
				PARTITION BY key
				ORDER BY CASE WHEN status = 'completed' THEN 0 ELSE 1 END, id
			) AS row_number
			FROM transactions
		) WHERE row_number > 1
	)`); err != nil {
		return err
	}
	if _, err := db.Exec(`CREATE UNIQUE INDEX IF NOT EXISTS transactions_key_unique ON transactions(key)`); err != nil {
		return err
	}
	return nil
}

func (l *Ledger) Recover() {
	rows, err := l.db.Query("SELECT id, key, account, amount FROM transactions WHERE status = 'pending'")
	if err != nil {
		return
	}
	var pending []TxRequest
	for rows.Next() {
		var req TxRequest
		if err := rows.Scan(&req.ID, &req.Key, &req.Account, &req.Amount); err != nil {
			continue
		}
		pending = append(pending, req)
	}
	rows.Close()
	for _, req := range pending {
		l.processOne(req)
	}
}

// EnsurePending uses SQLite's unique key constraint as the durable source of
// truth. Concurrent duplicate submissions all obtain the same transaction.
func (l *Ledger) EnsurePending(key, account string, amount int) (*Transaction, error) {
	tx, err := l.db.Begin()
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()

	var existing Transaction
	err = tx.QueryRow(
		"SELECT id, key, account, amount, status FROM transactions WHERE key = ?", key,
	).Scan(&existing.ID, &existing.Key, &existing.Account, &existing.Amount, &existing.Status)
	if err == nil {
		if err := tx.Commit(); err != nil {
			return nil, err
		}
		return &existing, nil
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return nil, err
	}

	res, err := tx.Exec(
		"INSERT INTO transactions(key, account, amount, status) VALUES(?, ?, ?, 'pending')",
		key, account, amount,
	)
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return &Transaction{ID: id, Key: key, Account: account, Amount: amount, Status: "pending"}, nil
}

func (l *Ledger) ProcessLoop(ch <-chan TxRequest) {
	for req := range ch {
		l.processOne(req)
	}
}

// processOne deliberately keeps the account update and completion update in
// one SQLite transaction. A crash can therefore leave either both changes or
// neither, never a debit without a completed marker (or the reverse).
func (l *Ledger) processOne(req TxRequest) {
	tx, err := l.db.Begin()
	if err != nil {
		panic(err)
	}
	defer tx.Rollback()

	var status string
	err = tx.QueryRow("SELECT status FROM transactions WHERE id = ?", req.ID).Scan(&status)
	if errors.Is(err, sql.ErrNoRows) {
		if req.Done != nil {
			close(req.Done)
		}
		return
	}
	if err != nil {
		panic(err)
	}
	if status != "pending" {
		if err := tx.Commit(); err != nil {
			panic(err)
		}
		if req.Done != nil {
			close(req.Done)
		}
		return
	}

	if _, err := tx.Exec(
		"INSERT INTO accounts(name, balance) VALUES(?, -?) ON CONFLICT(name) DO UPDATE SET balance = balance - ?",
		req.Account, req.Amount, req.Amount,
	); err != nil {
		panic(err)
	}
	if _, err := tx.Exec(
		"UPDATE transactions SET status = 'completed' WHERE id = ? AND status = 'pending'",
		req.ID,
	); err != nil {
		panic(err)
	}
	if err := tx.Commit(); err != nil {
		panic(err)
	}
	if req.Done != nil {
		close(req.Done)
	}
}

func (l *Ledger) GetTransaction(key string) *Transaction {
	var tx Transaction
	err := l.db.QueryRow(
		"SELECT key, account, amount, status FROM transactions WHERE key = ? AND status = 'completed'", key,
	).Scan(&tx.Key, &tx.Account, &tx.Amount, &tx.Status)
	if err != nil {
		return nil
	}
	return &tx
}

func (l *Ledger) GetAccount(name string) (int, bool) {
	var balance int
	err := l.db.QueryRow("SELECT balance FROM accounts WHERE name = ?", name).Scan(&balance)
	if err != nil {
		return 0, false
	}
	return balance, true
}
